import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'feature-card-1';
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader('/prism-mock/home/nodes/feature-card.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const grainStrength = uniform(0.035);

  if (map) {
    const texNode = texture(map, uv());

    // simple procedural grain based on uv (static, no interaction/animation)
    const grain = uv().x.mul(12.9898).add(uv().y.mul(78.233)).sin().mul(43758.5453).fract();
    const grainSigned = grain.sub(0.5).mul(grainStrength);

    const inkColor = vec4(0.086, 0.086, 0.114, 1.0); // #16161d
    const engineeredGradient = mix(texNode, inkColor, float(0.04));

    const finalColor = vec4(
      engineeredGradient.r.add(grainSigned),
      engineeredGradient.g.add(grainSigned),
      engineeredGradient.b.add(grainSigned),
      engineeredGradient.a
    );

    material.colorNode = finalColor;
  } else {
    material.colorNode = vec4(0.086, 0.086, 0.114, 1.0);
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'feature-card-1-mesh';
  group.add(mesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return group;
}
